begin;
create table if not exists public.bawaex_subscription_payments(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,plan_id uuid not null references public.plans(id),billing_interval text not null check(billing_interval in('MONTHLY','YEARLY')),amount_xof integer not null check(amount_xof>0),reference text not null unique,link_code text unique,payment_url text,status text not null default 'CREATING' check(status in('CREATING','PENDING','SUCCEEDED','FAILED','EXPIRED','CANCELLED')),collection_id text unique,processed_at timestamptz,expires_at timestamptz,error_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists bawaex_one_open_per_org on public.bawaex_subscription_payments(organization_id) where status in('CREATING','PENDING');
alter table public.bawaex_subscription_payments enable row level security;
drop policy if exists bawaex_users_read_own on public.bawaex_subscription_payments;create policy bawaex_users_read_own on public.bawaex_subscription_payments for select to authenticated using(user_id=auth.uid() or public.is_platform_admin());
create table if not exists public.bawaex_webhook_events(id uuid primary key default gen_random_uuid(),event_key text not null unique,event_type text not null,collection_id text,received_at timestamptz not null default now(),processed_at timestamptz,status text not null default 'RECEIVED' check(status in('RECEIVED','PROCESSED','IGNORED','FAILED')),error_message text);
alter table public.bawaex_webhook_events enable row level security;
create or replace function public.activate_bawaex_subscription(p_payment_id uuid,p_collection_id text)
returns jsonb language plpgsql security definer set search_path=public as $$declare p public.bawaex_subscription_payments;s uuid;e timestamptz;begin select * into p from public.bawaex_subscription_payments where id=p_payment_id for update;if not found then raise exception 'Paiement introuvable';end if;if p.status='SUCCEEDED' then return jsonb_build_object('already_processed',true,'payment_id',p.id);end if;if p.status not in('CREATING','PENDING')then raise exception 'Paiement non activable';end if;e:=now()+case when p.billing_interval='YEARLY'then interval '1 year'else interval '1 month'end;update subscriptions set status='EXPIRED',updated_at=now() where organization_id=p.organization_id and status in('TRIAL','ACTIVE','PAST_DUE');insert into subscriptions(organization_id,plan_id,owner_user_id,status,billing_interval,provider,provider_reference,current_period_end)values(p.organization_id,p.plan_id,p.user_id,'ACTIVE',p.billing_interval,'BAWAEX',coalesce(p_collection_id,p.reference),e)returning id into s;update bawaex_subscription_payments set status='SUCCEEDED',collection_id=coalesce(p_collection_id,collection_id),processed_at=now(),updated_at=now() where id=p.id;return jsonb_build_object('already_processed',false,'payment_id',p.id,'subscription_id',s,'current_period_end',e);end$$;
revoke all on function public.activate_bawaex_subscription(uuid,text) from public,anon,authenticated;grant execute on function public.activate_bawaex_subscription(uuid,text) to service_role;notify pgrst,'reload schema';commit;
